package net.minecraft.resources; public final class FileToIdConverter { final String p,e; private FileToIdConverter(String p,String e){this.p=p;this.e=e;} public static FileToIdConverter json(String p){return new FileToIdConverter(p,".json");} public Identifier idToFile(Identifier i){return i.withPath(p+"/"+i.getPath()+e);} public Identifier fileToId(Identifier i){String x=i.getPath();return i.withPath(x.substring(p.length()+1,x.length()-e.length()));} public boolean matches(Identifier i){return prefixMatches(i)&&extensionMatches(i);} public boolean prefixMatches(Identifier i){return i.getPath().startsWith(p);} public boolean extensionMatches(Identifier i){return i.getPath().endsWith(e);} public String prefix(){return p;} public String extension(){return e;} }
